<a href="<?= e(route_url('/admin/reviews')) ?>" class="text-link small muted" style="margin-bottom:22px"><?= icon('arrow-left',15) ?> Back to the review queue</a><div class="page-header"><div><span class="eyebrow">REVIEW THE WORK. ENCOURAGE THE PERSON.</span><h1><?= e($submission['title']) ?></h1><p>Submitted by <?= e($submission['full_name']) ?> · <?= niceDate($submission['submitted_at'],'M j, Y · H:i') ?> UTC</p></div><?= badge($submission['status']) ?></div><div class="two-column"><div class="stack"><section class="card form-card"><h2 class="form-section-title">The learner’s work.</h2><div class="review-response"><?= e($submission['content']?:'No text response submitted.') ?></div><div class="page-actions"><?php if($submission['project_url']): ?><a class="btn btn-secondary btn-small" href="<?= e($submission['project_url']) ?>" target="_blank" rel="noopener noreferrer">Open project <?= icon('arrow-up-right',15) ?></a><?php endif; ?><?php if($submission['file_key']): ?><a class="btn btn-secondary btn-small" href="<?= e(route_url('/downloads/submissions/' . ((int)$submission['id']))) ?>"><?= icon('download',15) ?> <?= e($submission['file_name']) ?></a><?php endif; ?></div><div class="separator"></div><h3 style="font-size:14px;margin-bottom:15px">The assignment brief</h3><div class="prose"><?= lessonHtml($submission['instructions']) ?></div></section>
<?php if($feedback): ?><section class="card card-pad"><div class="card-header"><h2>Feedback along the way.</h2></div><?php foreach($feedback as $f): ?><article class="feedback-card"><h4><span><?= e($f['full_name']) ?></span><?= badge($f['action']) ?></h4><p><?= e($f['feedback']) ?></p><small><?= niceDate($f['created_at'],'M j, H:i') ?> UTC<?= $f['score']!==null?' · Score '.e($f['score']):'' ?></small></article><?php endforeach; ?></section><?php endif; ?>
<?php if($history): ?><section class="card card-pad"><div class="card-header"><h2>Submission history.</h2></div><?php foreach($history as $h): ?><details class="review-prompt"><summary style="font-size:12px;cursor:pointer"><?= e(ucwords(str_replace('_',' ',$h['status']))) ?> · <?= niceDate($h['created_at'],'M j, Y · H:i') ?> UTC</summary><div class="review-response"><?= e($h['content']) ?></div><?php if($h['project_url']): ?><a href="<?= e($h['project_url']) ?>" class="text-link small" target="_blank" rel="noopener noreferrer">Snapshot project link <?= icon('arrow-up-right',14) ?></a><?php endif; ?></details><?php endforeach; ?></section><?php endif; ?></div><aside class="stack"><section class="card form-card"><h2 class="form-section-title">Give the next step a little clarity.</h2><p class="form-section-description">Acceptance requires at least <?= (int)$submission['passing_score'] ?> / <?= (int)$submission['max_score'] ?> points. Only acceptance awards completion and eligible XP.</p><?php if(in_array($submission['status'],['submitted','resubmitted','under_review','graded'],true)): ?><form action="<?= e(route_url('/api/admin/reviews/' . ((int)$submission['id']))) ?>" method="post" data-api data-confirm="Save this review and make the feedback available to the learner? Acceptance may award XP and unlock their next stage."><?= csrfField() ?><div class="field"><label for="review-status">Review outcome</label><select id="review-status" name="status"><option value="under_review">Under review</option><option value="revision_requested">Request a revision</option><option value="graded">Graded · not yet accepted</option><option value="accepted">Accepted · award completion</option></select></div><div class="field"><label for="score">Score <span>· required for grading or acceptance</span></label><input id="score" name="score" type="number" min="0" max="<?= (int)$submission['max_score'] ?>" value="<?= e($submission['score']??'') ?>"></div><div class="field"><label for="feedback">Constructive feedback</label><textarea id="feedback" name="feedback" minlength="3" maxlength="10000" required placeholder="What worked well? What specific improvement would help?" style="min-height:180px"></textarea></div><button class="btn btn-primary btn-block">Save a thoughtful review <?= icon('check',16) ?></button></form><?php else: ?><div class="notice info"><?= icon('info',18) ?><p><?= $submission['status']==='accepted'?'This submission is accepted. Its completion and reward records are preserved.':'This submission is waiting for learner action or is not submitted. Review it after the next submission.' ?></p></div><?php endif; ?></section><section class="card card-pad"><div class="card-header"><h2>The published rubric.</h2></div><?php foreach($rubrics as $r): ?><div class="key-value"><span><?= e($r['criterion']) ?></span><strong><?= (int)$r['max_points'] ?> pts</strong></div><?php endforeach; ?><div class="key-value"><span>Total available</span><strong><?= (int)$submission['max_score'] ?></strong></div></section><?php if($currentUser['role']==='administrator'): ?><section class="card form-card"><h2 class="form-section-title">Give it the right reviewer.</h2><p class="form-section-description">Reviewers can access only explicitly assigned work.</p><form action="<?= e(route_url('/api/admin/assign-reviewer/assignment/' . ((int)$submission['id']))) ?>" method="post" data-api><?= csrfField() ?><div class="field"><label for="reviewer-id">Authorised reviewer</label><select id="reviewer-id" name="reviewer_id"><?php foreach($reviewers as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $r['id']===$submission['reviewer_id']?'selected':'' ?>><?= e($r['full_name']) ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary btn-block">Assign reviewer</button></form></section><?php endif; ?></aside></div>
